/* Noetic Core Utils v2.0 - Advanced Analytics */
(function(){
const E='https://noetic-presence.mselayet.workers.dev',I=3e4,SK='nlp_sid',DK='nlp_did',VK='nlp_new';
let sid=sessionStorage.getItem(SK);
if(!sid){sid='s_'+Date.now().toString(36)+Math.random().toString(36).substr(2,9);sessionStorage.setItem(SK,sid)}
let did=localStorage.getItem(DK);
let isNew=false;
if(!did){did='d_'+Date.now().toString(36)+Math.random().toString(36).substr(2,12);localStorage.setItem(DK,did);localStorage.setItem(VK,'1');isNew=true}else{isNew=localStorage.getItem(VK)==='1';localStorage.removeItem(VK)}
let st=Date.now(),sd=0,lsd=0,pt=0;
const gs=()=>`${screen.width}x${screen.height}`;
const ss=()=>{const h=document.documentElement.scrollHeight-window.innerHeight;if(h<=0)return 100;const p=Math.round((window.scrollY/h)*100);if(p>sd)sd=p;return sd};
const hb=()=>{pt=Math.round((Date.now()-st)/1000);const d={sessionId:sid,deviceId:did,page:location.pathname,referrer:document.referrer,scrollDepth:sd,timeOnPage:pt,isNewVisitor:isNew,screenSize:gs(),language:navigator.language||'unknown'};fetch(E+'/presence/heartbeat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(d),keepalive:true}).catch(()=>{});isNew=false};
const ev=(t,data)=>{fetch(E+'/presence/event',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({type:t,sessionId:sid,deviceId:did,...data}),keepalive:true}).catch(()=>{})};
const lv=()=>{pt=Math.round((Date.now()-st)/1000);navigator.sendBeacon(E+'/presence/leave',JSON.stringify({sessionId:sid,timeOnPage:pt,page:location.pathname}))};
window.addEventListener('scroll',()=>{const ns=ss();if(ns-lsd>=25){lsd=ns;ev('scroll',{page:location.pathname,depth:ns})}},{passive:true});
document.addEventListener('click',(e)=>{const t=e.target.closest('a');if(t&&t.href){const u=new URL(t.href,location.origin);if(u.hostname!==location.hostname){ev('exitLink',{url:t.href,page:location.pathname})}}const el=e.target.tagName+(e.target.id?'#'+e.target.id:'')+(e.target.className?'.'+e.target.className.split(' ')[0]:'');ev('click',{page:location.pathname,element:el,x:e.clientX,y:e.clientY})});
const si=document.querySelector('input[type="search"],.search-bar,#search');if(si){let lt='';si.addEventListener('input',(e)=>{clearTimeout(si._t);si._t=setTimeout(()=>{const q=e.target.value.trim();if(q&&q!==lt&&q.length>2){lt=q;ev('search',{query:q,page:location.pathname})}},1000)})}
hb();setInterval(hb,I);
window.addEventListener('beforeunload',lv);
document.addEventListener('visibilitychange',()=>{if(document.hidden){lv()}else{st=Date.now();sd=0;hb()}});
})();
